import{_ as d,C as a,o as r,c,j as t,a as n,E as i,a4 as s}from"./chunks/framework.cdJ1L9ZC.js";const g=JSON.parse('{"title":"Overview","description":"Every part of the library on one screen. Not a grid of specimens — the components are laid out the way an application would lay them out, so you can see…","frontmatter":{"title":"Overview","order":1,"aside":false},"headers":[],"relativePath":"examples/overview.md","filePath":"en/examples/overview.md","lastUpdated":1786774258000}'),h={name:"examples/overview.md"};function l(p,e,m,P,u,M){const o=a("Demo");return r(),c("div",null,[e[0]||(e[0]=t("h1",{id:"overview",tabindex:"-1"},[n("Overview "),t("a",{class:"header-anchor",href:"#overview","aria-label":'Permalink to "Overview"'},"​")],-1)),e[1]||(e[1]=t("p",{class:"mp-lede"},"Every part of the library on one screen. Not a grid of specimens — the components are laid out the way an application would lay them out, so you can see whether the sizes, the baselines and the surfaces agree with each other once they are side by side.",-1)),i(o,{src:"showcase/app",minHeight:2e3}),e[2]||(e[2]=s('<h2 id="what-to-look-at" tabindex="-1">What to look at <a class="header-anchor" href="#what-to-look-at" aria-label="Permalink to &quot;What to look at&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Block</th><th>Components used</th><th>Worth noticing</th></tr></thead><tbody><tr><td>App bar</td><td><code>MPIcon</code> <code>MPTextField</code> <code>MPBadge</code> <code>MPTooltip</code> <code>MPIconButton</code> <code>MPMenu</code> <code>MPAvatar</code></td><td>The bar itself is a <code>&lt;header&gt;</code> with <code>bg-mp-surface-container</code> on it — the tokens are the API for the parts that are not components</td></tr><tr><td>Trail</td><td><code>MPBreadcrumb</code> <code>MPPill</code></td><td>A pill is where the state that belongs to no single control goes; the spinner inside it is <code>MPProgressCircular</code> at <code>xs</code></td></tr><tr><td>Alert</td><td><code>MPAlert</code></td><td>One thing needs attention, said once, at the top, with its own <code>action</code></td></tr><tr><td>Figures</td><td><code>MPGrid</code> <code>MPGridItem</code> <code>MPCard</code> <code>MPChip</code></td><td><code>MPGrid</code> divides on Material&#39;s window size classes — 600, 840, 1200dp — not on Tailwind&#39;s breakpoints</td></tr><tr><td>Controls</td><td><code>MPSegmentedButton</code> <code>MPSelect</code> <code>MPButtonGroup</code> <code>MPButton</code></td><td>At <code>size=&quot;sm&quot;</code> all four are the same height, so the row keeps one baseline with no margins written down</td></tr><tr><td>What&#39;s new</td><td><code>MPCarousel</code></td><td>Built on scroll snap, so it swipes on a phone and reverses direction under RTL</td></tr><tr><td>Deploys</td><td><code>MPTabs</code> <code>MPTable</code> <code>MPChip</code> <code>MPPagination</code></td><td>The table is rendered from a column list, so the headings and the cells cannot drift apart</td></tr><tr><td>Forms</td><td><code>MPCard</code> <code>MPTextField</code> <code>MPDivider</code> <code>MPChip</code> <code>MPCheckbox</code> <code>MPRadioGroup</code> <code>MPSwitch</code> <code>MPSlider</code></td><td>Every control takes <code>label</code>, and the ones with something more to say take <code>description</code> — the same two slots on all of them</td></tr><tr><td>Release</td><td><code>MPTimeline</code> <code>MPHighlight</code> <code>MPShortcut</code> <code>MPBlockquote</code> <code>MPProgressLinear</code> <code>MPList</code> <code>MPRating</code></td><td>Type in the search field at the top: <code>MPHighlight</code> <strong>is</strong> the search, and the marks in the release note appear as you type</td></tr><tr><td>Bottom bar</td><td><code>MPBottomNavigation</code></td><td><code>position=&quot;static&quot;</code> puts it in the layout instead of against the window, which is what makes it previewable at all</td></tr></tbody></table><p>Messages come from <code>MPSnackbarProvider</code>, once, around the whole screen — the buttons that post them only say what happened.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li>The same parts, built into three whole screens: <a href="./concept-landing">Landing page</a>, <a href="./concept-dashboard">Admin dashboard</a>, <a href="./concept-signup">Sign-up page</a>.</li><li>Per-component props and examples are under <a href="./../components/">Components</a>.</li><li>What the shared props mean is in <a href="./../design/prop-conventions">Prop conventions</a>.</li></ul>',5))])}const v=d(h,[["render",l]]);export{g as __pageData,v as default};
